// drums.h -- the drum kit: what each of the eight drum lanes plays.
//
// Seven stock kits come from AMY's drum banks (drum_kits.h, generated by
// tools/gen-drums.py): TR-808, TR-909, Linn 9000, MR-12, Tokyo Synthetics,
// Power and Percussion. Any lane can then play any of the 155 drum samples,
// or a sample of your own (the MIC take, put on the lane), tuned and
// levelled: a kit of your own. Pure data: tests/ checks it on the build
// machine; engine.c plays it.
#pragma once

#include <stdbool.h>
#include <stdint.h>

#define DRUM_LANES 8          // KICK SNARE HAT OPEN CLAP RIM TOM CRASH (music.c's drum keys)
#define DRUM_USER_PRESET 230  // + lane: the lane's own sample, an AMY memory preset
#define DRUM_TUNE_MAX 24      // semitones either way
#define DRUM_LEVEL_MAX 200    // percent
#define DRUM_LANE_HAT 2       // the closed hat chokes the open one
#define DRUM_LANE_OPEN 3

typedef struct {
    uint16_t preset;  // a drum sample (kDrumSamples) or DRUM_USER_PRESET + lane
    int8_t tune;      // semitones from the sample's own pitch
    uint8_t level;    // percent: 100 = as the kit has it
} DrumLane;

typedef struct {
    uint8_t kit;     // the stock kit it started from (0..DRUM_KITS-1)
    uint8_t edited;  // bit n: lane n has been changed from the stock kit
    DrumLane lane[DRUM_LANES];
} DrumKit;

int drum_kit_count(void);
const char *drum_kit_name(int kit);
void drum_kit_stock(DrumKit *k, int kit);  // a stock kit, as it comes
void drum_kit_clamp(DrumKit *k);           // sanitise (after loading)

// A lane's note to play (the sample's root + tune) and its velocity scale
// (the sample's level in AMY's kits x the lane's level).
float drum_lane_note(const DrumKit *k, int lane);
float drum_lane_gain(const DrumKit *k, int lane);
// What a lane plays, for the screen: "909SD", or "OWN SAMPLE".
const char *drum_lane_sample_name(const DrumKit *k, int lane);
const char *drum_lane_bank_name(const DrumKit *k, int lane);
const char *drum_lane_name(int lane);  // "KICK"...

// The lane a drum note (MIDI) belongs to, or -1.
int drum_lane_of_note(int note);

// Step a lane's sample through all of them (dir +-1), across the banks.
void drum_lane_step(DrumKit *k, int lane, int dir);
// Put the lane on its own sample (DRUM_USER_PRESET + lane).
void drum_lane_use_own(DrumKit *k, int lane);
void drum_lane_set_tune(DrumKit *k, int lane, int semis);
void drum_lane_set_level(DrumKit *k, int lane, int percent);
